#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    int *a = (int *)malloc(n * sizeof(int));
    if (!a) return 1;

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    /* Ordena as notas em ordem decrescente.
       A resposta e a K-esima maior nota: com C = a[k-1],
       exatamente os K maiores (ou mais, em caso de empates)
       candidatos ficam com nota >= C, e qualquer C maior
       deixaria menos de K aprovados. */
    qsort(a, n, sizeof(int), cmp_desc);

    printf("%d\n", a[k - 1]);

    free(a);
    return 0;
}
